        color: cardTypeColor(card, cardTypes),
        document,
        id,
        key: `card:${card.header.internalId ?? card.path}`,
        kind: tabKind(card, actionsFolder),
        label,
        title: id ? label.slice(id.length + 1) : label,
    }
}

